mapper.insert:

INSERT INTO DATASOURCE (
      SOURCE_ID
    , SOURCE_NAME
    , OWNER_ID
    , STATUS
    , FIRST_REGISTER_BRANCH
    , FIRST_REGISTER_USER
    , FIRST_REGISTER_DATE
    , FIRST_REGISTER_TIME
    , LAST_CHANGE_BRANCH
    , LAST_CHANGE_USER
    , LAST_CHANGE_DATE
    , LAST_CHANGE_TIME
) VALUES (
      #{sourceId}
    , #{sourceName}
    , #{ownerId}
    , 'Y'
    , #{firstRegisterBranch}
    , #{firstRegisterUser}
    , #{firstRegisterDate}
    , #{firstRegisterTime}
    , #{lastChangeBranch}
    , #{lastChangeUser}
    , #{lastChangeDate}
    , #{lastChangeTime}
)

mapper.update:

UPDATE DATASOURCE
   SET SOURCE_NAME        = #{sourceName}
     , OWNER_ID           = #{ownerId}
     , LAST_CHANGE_BRANCH = #{lastChangeBranch}
     , LAST_CHANGE_USER   = #{lastChangeUser}
     , LAST_CHANGE_DATE   = #{lastChangeDate}
     , LAST_CHANGE_TIME   = #{lastChangeTime}
 WHERE SOURCE_ID = #{sourceId}


UPDATE DATASOURCE_UPLOAD_LOG
   SET TOTAL_ROWS = #{totalRows}
 WHERE UPLOAD_ID  = #{uploadId}
